import { z } from "zod";
import { supabase } from "@/integrations/supabase/client";
import { publicLegacyDisplayName } from "@/lib/legacy-display-name";

// Do not modify autogenerated Supabase types until the RPC is installed.
// Parse the public JSON shape strictly before exposing it to components.
const profileSchema = z.object({
  wp_post_id: z.number().int().positive().max(Number.MAX_SAFE_INTEGER),
  display_name: z.string().min(1).max(80),
  sector_tags: z.array(z.string().min(1).max(80)),
  country_label: z.literal("Brasil"),
  validation_status: z.literal("em_validacao"),
}).strict();
const pageSchema = z.object({
  profiles: z.array(profileSchema).max(24),
  count: z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER),
}).strict();
export type PublicLegacyArchiveProfile = z.infer<typeof profileSchema>;
export type PublicLegacyArchivePage = {
  profiles: PublicLegacyArchiveProfile[];
  count: number;
};
type ArchiveRpcClient = {
  rpc(
    name: "eut_public_legacy_archive_page",
    args: { _limit: number; _offset: number },
  ): PromiseLike<{ data: unknown; error: unknown }>;
};
const archiveRpc = supabase as unknown as ArchiveRpcClient;

export async function readPublicLegacyArchivePage(
  limit: 4 | 24,
  offset: number,
): Promise<PublicLegacyArchivePage> {
  if ((limit !== 4 && limit !== 24) || !Number.isSafeInteger(offset) ||
      offset < 0 || offset > 24000) {
    throw new Error("Parâmetros inválidos do acervo público.");
  }
  const { data, error } = await archiveRpc.rpc("eut_public_legacy_archive_page", {
    _limit: limit, _offset: offset,
  });
  if (error) throw new Error("Não foi possível consultar o acervo público.");
  const parsed = pageSchema.safeParse(data);
  if (!parsed.success) throw new Error("Resposta inválida do acervo público.");
  return {
    count: parsed.data.count,
    profiles: parsed.data.profiles.map((p) => {
      const visible = publicLegacyDisplayName(p.display_name);
      return {
        ...p,
        display_name: visible.display === "Técnico" ? "Técnico" : p.display_name.trim(),
        sector_tags: p.sector_tags
          .filter((t) => t.trim() && (t.trim() === "Técnico" ||
            publicLegacyDisplayName(t).display !== "Técnico"))
          .map((t) => t.trim()),
      };
    }),
  };
}
